export function usdcBorderSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !USDC_BORDER_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Invalid USDC borders SVG variant');
  }
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
